import json
from pathlib import Path
for name in ['qualification.json','gate4_runtime.json','gate4.json','gate5.json','public_asset_rights.json','security_privacy.json','verify_public.json']:
 p=Path('QA/release')/name
 if not p.exists():
  print(name, 'MISSING')
  continue
 try:
  d=json.loads(p.read_text())
  print('\\n'+name)
  for k in ['status','candidate_revision','candidate_head','candidate_tree','tested_sha','artifact_sha256','exact_candidate_bound','comparison_mode','performance_status','external_provider','verify_public_status']:
   if k in d: print(k, d[k])
  for k in ['gate4','gate5','security_privacy','public_asset_rights','performance','contract_failures','verify_required']:
   if k in d: print(k, d[k] if isinstance(d[k],(str,int,bool)) else type(d[k]).__name__)
 except Exception as e: print(name, 'ERROR', e)
